BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch12$PT122-S2-Q24$batch12$ AND q.stimulus=$batch12$Judicial punishment’s power to deter people from committing crimes is a function of the severity of the penalty and the likelihood of one’s actually receiving the penalty. Occasionally, juries decide that a crime’s penalty is too severe and so refuse to convict a person they are convinced has committed that crime. Thus, increasing the penalty may decrease the deterrent power of judicial punishment.$batch12$ AND q.prompt=$batch12$The pattern of reasoning in which one of the following arguments is most similar to the pattern of reasoning in the argument above?$batch12$ AND q.correct_choice=$batch12$A$batch12$) THEN RAISE EXCEPTION 'Question changed: PT122-S2-Q24'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch12$PT122-S2-Q24$batch12$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT122-S2-Q24'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch12$PT122-S2-Q24$batch12$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch12$Conclusion$batch12$, $batch12$Increasing the penalty may decrease deterrence.$batch12$), (1, $batch12$Evidence$batch12$, $batch12$Deterrence depends on severity and on the likelihood of being penalized. Juries sometimes refuse to convict when penalties seem too severe.$batch12$), (2, $batch12$Evaluate$batch12$, $batch12$An outcome depends on two factors. Raising one factor can lower the other. So raising the first may hurt the outcome.$batch12$), (3, $batch12$Goal$batch12$, $batch12$Outcome depends on X and Y; more X can mean less Y; so more X may mean less outcome.$batch12$)) v(position,label,body) WHERE q.qid=$batch12$PT122-S2-Q24$batch12$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch12$A$batch12$, $batch12$Job success depends on quality and time spent. Too much time can lower quality. So more time may mean less success. Same recipe.$batch12$), ($batch12$B$batch12$, $batch12$One factor, safety features, leading to aggressive driving. No two-factor outcome.$batch12$), ($batch12$C$batch12$, $batch12$This compares two surgeries with a tradeoff. It's not one factor undercutting another within a single outcome.$batch12$), ($batch12$D$batch12$, $batch12$This recommends where to focus effort.$batch12$), ($batch12$E$batch12$, $batch12$This reverses the relationship between price and reputation.$batch12$)) v(letter,body) WHERE q.qid=$batch12$PT122-S2-Q24$batch12$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
